css:
[data-bz-node="ph"]{color:#fff}
[data-bz-node="ph-media"]{position:absolute;inset:0;z-index:0}
/* The photo fills the band by being positioned against it. A height:100%
   chain cannot resolve here: the column takes its height from grid stretch,
   not an explicit value, so every percentage below it falls back to auto. */
[data-bz-node="ph-media"] .bz-col,[data-bz-node="ph-media"] .bz-block,[data-bz-node="ph-media"] .bz-container{position:static;padding:0;margin:0}
[data-bz-node="ph-media"] .bz-figure{position:absolute;inset:0;margin:0}
[data-bz-node="ph-media"] img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;border-radius:0}
/* The copy stack sets its own rhythm with margins; .bz-block's 16px top and
   bottom made the band 32px taller than the reference. */
[data-bz-node="ph-copy"] .bz-block{padding-block:0}
[data-bz-node="ph-body"]{background:linear-gradient(90deg,rgba(14,15,19,.92) 0%,rgba(14,15,19,.75) 45%,rgba(14,15,19,.25) 100%)}
[data-bz-node="ph-copy"] .bz-eyebrow{color:#fff;font-family:var(--font-heading);font-weight:600;font-size:13px;letter-spacing:.14em;text-transform:uppercase;margin:0 0 16px;border-left:4px solid #C41230;padding-left:12px}
[data-bz-node="ph-title"] h1{font-family:var(--font-heading);font-weight:700;font-size:clamp(40px,6vw,80px);line-height:1;text-transform:uppercase;color:#fff;margin:0 0 24px;letter-spacing:0}
[data-bz-node="ph-lead"] p{font-size:18px;line-height:1.6;color:#fff;margin:0;max-width:560px}
[data-bz-node="ph-ctas"] .bz-btns{display:flex;flex-wrap:wrap;gap:16px;margin:0}
[data-bz-node="ph-ctas"] .bz-btn{font-family:var(--font-heading);font-weight:600;font-size:15px;letter-spacing:.1em;text-transform:uppercase;border-radius:0}
[data-bz-node="ph-ctas"] .bz-btn--primary{background:#C41230;color:#fff;padding:18px 32px;border:0}
[data-bz-node="ph-ctas"] .bz-btn--primary:hover{background:#8f0d21;color:#fff}
[data-bz-node="ph-ctas"] .bz-btn--secondary{background:transparent;color:#fff;border:2px solid #fff;padding:16px 32px}
[data-bz-node="ph-ctas"] .bz-btn--secondary:hover{background:rgba(255,255,255,.15);border-color:#fff;color:#fff}
[data-bz-node="ph-copy"] .bz-eyebrow{line-height:normal}
[data-bz-node="ph-lead"]{margin-bottom:32px}
